/**
 * @file Real d1 AMR map fixture for the map-canvas editor's practical
 * Storybook story and e2e demo.
 *
 * Source: a real robot map export, `cuc_1_north-0826-01`
 * (`grid_map.yaml` + `grid_map.pgm` + `road_map.xml`), not a synthetic
 * or hand-authored scene. The occupancy raster and the 22-vertex /
 * 22-edge road graph below were both generated by machine-parsing those
 * source files (never hand-transcribed), so they cannot drift from the
 * export.
 *
 * Raster: the source PGM is 1413x824 px at 0.05 m/px (P5 binary,
 * `negate: 0`). It was downsampled by an integer factor of 2 using a
 * min-pool (darkest-wins, so thin obstacles survive downsampling) to keep
 * the embedded fixture small — 706x412 px at 44 KiB as a base64 PNG data
 * URI. Downsampling by factor F coarsens F source pixels into 1 output
 * pixel per axis, so the fixture's metres-per-pixel is the source
 * resolution times F: 0.05 * 2 = 0.1 m/px. The world origin
 * (bottom-left pixel corner, in map frame metres) is unaffected by
 * downsampling and is carried through unchanged from `grid_map.yaml`.
 *
 * Road graph: `road_map.xml` (map editor v0.6) declares 22 `<vertex>`
 * elements (13 stations carrying a vendor `defineType` — e.g. "home",
 * "entrancein", "wc" — and 9 plain path points, which do NOT carry
 * `defineType` at all in the source, not even as an empty string) and 22
 * `<edge>` elements. The XML's edge `src_id`/`dst_id` attributes are
 * UNPADDED decimal strings ("11") while vertex `id` attributes are
 * zero-padded ("0011"); edges below have been normalised to the padded
 * id form so `points` can be looked up by `edge.src` / `edge.dst`
 * directly without re-deriving the padding at every call site.
 *
 * Pure data + types only: no React, no imports from elsewhere in this
 * package.
 */

export type CucRoadPointType = 2 | 100;

export type CucRoadGraphPoint = {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly yaw: number;
  readonly type: CucRoadPointType;
  /** Present only on stations (type 2); absent (not "") on path points. */
  readonly defineType?: string;
};

export type CucRoadGraphEdge = {
  readonly id: string;
  /** Normalised to the zero-padded vertex id form (see file header). */
  readonly src: string;
  /** Normalised to the zero-padded vertex id form (see file header). */
  readonly dst: string;
  readonly oneWay: boolean;
  readonly single: boolean;
};

export type CucRoadGraph = {
  readonly points: readonly CucRoadGraphPoint[];
  readonly edges: readonly CucRoadGraphEdge[];
};

export type CucRaster = {
  readonly dataUri: string;
  readonly pixelWidth: number;
  readonly pixelHeight: number;
  readonly resolution: number;
  readonly originX: number;
  readonly originY: number;
};

export const CUC_1_NORTH_RASTER: CucRaster = {
  dataUri:
    "data:image/png;base64,",
  pixelWidth: 706,
  pixelHeight: 412,
  resolution: 0.1,
  originX: -52.6681,
  originY: -32.6934,
};

